/*
 * DIR_$OLD_FIND_NET - the extra longword of the root entry for a node
 *
 * Original address: 0x00E55AFE
 * Size: 248 bytes (0x00E55AFE .. 0x00E55BF5)
 * Generated by: Claude Opus 5.5
 *
 * Also holds dir_$old_find_node_slot (0x00E559D6, 296 bytes, was
 * FUN_00e559d6; no map symbol, reached only by the `bsr' at 0x00E55B44).
 *
 * Frame: (0x8,A6) dir_uid (A3), (0xC,A6) node_ptr (A2).  A Pascal function:
 * the answer is in D0 (D2, preset 0).  A5 = OLD_DIR (0xE7FD24), unused.
 * Called by 0x00E4E81C.
 *
 * Blocks:
 *   0x00E55B14-0x00E55B32  result = 0; NAME_$LOCK_DIR(dir_uid, &handle,
 *                          1, 0, &status); failure goes to the exit
 *   0x00E55B36-0x00E55B54  dir_$old_find_node_slot(handle, *node_ptr, &rec,
 *                          &status); NAME_$UNLOCK_DIR(&unlock_status)
 *   0x00E55B56-0x00E55B66  found: result = rec.extra (status takes the
 *                          unlock status, which nobody reads)
 *   0x00E55B68-0x00E55B82  not found (0xE0007) in the root directory only:
 *   0x00E55B84-0x00E55B9E  REM_NAME_$FIND_NETWORK(dir_uid, node_ptr, &rec,
 *                          &status); failure goes to the exit
 *   0x00E55BA0-0x00E55BE0  UNMAP_CASE(rec.name, &rec.name_len, name, &0x20,
 *                          &name_len, &truncated); cache the entry with
 *                          name_$old_add_entry(dir_uid, 0, name, name_len,
 *                          &rec.uid, rec.extra, &unlock_status);
 *                          result = rec.extra
 *   0x00E55BE4-0x00E55BEA  ACL_$EXIT_SUPER(); return result
 *
 * Quirks reproduced:
 *   - ACL_$EXIT_SUPER runs on every exit though this routine never enters
 *     super mode.
 *   - The status is local: failures only show as a zero answer.
 *   - UNMAP_CASE gets the shared constant word 0x0020 at 0x00E544AE
 *     (`pea (-0x16fc,PC)' 0x00E55BA8).
 */

#include "dir/dir_internal.h"

/* `move.l #0x10000,-(SP)' 0x00E55B1A: NAME_$LOCK_DIR's two words 1, 0 */
#define OLD_FIND_NET_LOCK_MODE  1
#define OLD_FIND_NET_ACL_RIGHTS 0
/* `move.l #0xfffff,D2' 0x00E55A08: the node-id bits of a UID's low half */
#define OLD_FIND_NET_NODE_MASK  0x000FFFFFu

/*
 * dir_$old_find_node_slot (0x00E559D6) - search an old-format directory for
 * an in-use slot whose UID's low 20 bits equal node.
 *
 * Frame: (0x8,A6) handle (A2), (0xC,A6) node by value (D0), (0x10,A6) rec
 * (D5), (0x14,A6) status_ret.
 *
 *   0x00E559EA-0x00E55A4C  inline slots 1..hdr+4: type 1 and
 *                          (uid.low & 0xFFFFF) == node -> copy the name to
 *                          rec+4, the length byte as a word to rec+2, the
 *                          UID to rec+0x24, the extra longword to rec+0x2C
 *   0x00E55A50-0x00E55AE6  overflow blocks 1..hdr+0xA (stride 0x96): a
 *                          block whose byte +0x36F is 1 and when hdr+8 is at
 *                          least 1, its slots 1..hdr+8, same test and copy
 *   0x00E55ACE / 0x00E55AEA  status_$ok / status_$naming_name_not_found
 */
static void dir_$old_find_node_slot(uint32_t handle, uint32_t node,
                                    dir_$rep_entry_t *rec,
                                    status_$t *status_ret)
{
    uint8_t *dir = (uint8_t *)ARCH_VA_TO_PTR(handle);   /* A2 */
    uint8_t *block;                                     /* A1 */
    dir_$old_slot_t *slot = NULL;
    uint16_t n;                                         /* D1 */
    uint16_t m;                                         /* D3 */
    uint32_t block_off;                                 /* D2 */
    uint32_t slot_off;                                  /* D4 */
    int16_t k;

    /* 0x00E559EA-0x00E55A4C */
    if (*(uint16_t *)(dir + DIR_OLD_HDR_INLINE_SLOTS) != 0) {
        n = *(uint16_t *)(dir + DIR_OLD_HDR_INLINE_SLOTS) - 1;
        block = dir + DIR_OLD_SLOT_STRIDE;
        do {
            slot = (dir_$old_slot_t *)(block - DIR_OLD_INLINE_SLOT_BIAS);
            if (slot->type == DIR_OLD_SLOT_IN_USE &&
                (slot->uid.low & OLD_FIND_NET_NODE_MASK) == node) {
                goto found;
            }
            block += DIR_OLD_SLOT_STRIDE;
        } while (n-- != 0);
    }

    /* 0x00E55A50-0x00E55AE6 */
    if (*(uint16_t *)(dir + DIR_OLD_HDR_BLOCKS) != 0) {
        n = *(uint16_t *)(dir + DIR_OLD_HDR_BLOCKS) - 1;
        block_off = DIR_OLD_BLOCK_STRIDE;
        do {
            block = dir + block_off;
            if (block[DIR_OLD_BLOCK_TYPE] == DIR_OLD_SLOT_IN_USE &&
                *(uint16_t *)(dir + DIR_OLD_HDR_BLOCK_SLOTS) >= 1) {
                m = *(uint16_t *)(dir + DIR_OLD_HDR_BLOCK_SLOTS) - 1;
                slot_off = DIR_OLD_SLOT_STRIDE;
                do {
                    slot = (dir_$old_slot_t *)(block + slot_off +
                                               DIR_OLD_BLOCK_SLOT_BASE);
                    if (slot->type == DIR_OLD_SLOT_IN_USE &&
                        (slot->uid.low & OLD_FIND_NET_NODE_MASK) == node) {
                        goto found;
                    }
                    slot_off += DIR_OLD_SLOT_STRIDE;
                } while (m-- != 0);
            }
            block_off += DIR_OLD_BLOCK_STRIDE;
        } while (n-- != 0);
    }

    /* 0x00E55AEA */
    *status_ret = status_$naming_name_not_found;
    return;

found:
    /* 0x00E55A16-0x00E55A3E / 0x00E55AA0-0x00E55AC8 (the two arms are
     * identical but for the slot address) */
    for (k = 0; k < 0x20; k++) {                        /* dbf #0x1F */
        rec->name[k] = slot->name[k];
    }
    rec->name_len = slot->name_len;
    rec->uid.high = slot->uid.high;
    rec->uid.low = slot->uid.low;
    rec->extra = slot->extra;
    /* 0x00E55ACE */
    *status_ret = status_$ok;
}

uint32_t DIR_$OLD_FIND_NET(uid_t *dir_uid, uint32_t *node_ptr)
{
    uint8_t truncated;                  /* (-0x64,A6) */
    int16_t name_len;                   /* (-0x62,A6) */
    uint32_t handle;                    /* (-0x5C,A6) */
    status_$t status;                   /* (-0x58,A6) */
    status_$t unlock_status;            /* (-0x54,A6) */
    dir_$rep_entry_t rec;               /* (-0x50,A6) */
    char name[0x20];                    /* (-0x20,A6) */
    uint32_t result;                    /* D2 */

    /* 0x00E55B14-0x00E55B32 */
    result = 0;
    NAME_$LOCK_DIR(dir_uid, &handle, OLD_FIND_NET_LOCK_MODE,
                   OLD_FIND_NET_ACL_RIGHTS, &status);
    if (status == status_$ok) {
        /* 0x00E55B36-0x00E55B54 */
        dir_$old_find_node_slot(handle, *node_ptr, &rec, &status);
        NAME_$UNLOCK_DIR(&unlock_status);

        if (status == status_$ok) {
            /* 0x00E55B5C-0x00E55B60 */
            result = rec.extra;
            status = unlock_status;
        } else if (status == status_$naming_name_not_found &&
                   dir_uid->high == NAME_$ROOT_UID.high &&
                   dir_uid->low == NAME_$ROOT_UID.low) {
            /* 0x00E55B84-0x00E55B9E */
            REM_NAME_$FIND_NETWORK(dir_uid, node_ptr, &rec, &status);
            if (status == status_$ok) {
                /* 0x00E55BA0-0x00E55BE0 */
                UNMAP_CASE((char *)rec.name, (int16_t *)&rec.name_len, name,
                           (int16_t *)&name_$leaf_max_len_00e544ae,
                           &name_len, &truncated);
                name_$old_add_entry(dir_uid, 0, name, (uint16_t)name_len,
                                    &rec.uid, rec.extra, &unlock_status);
                result = rec.extra;
            }
        }
    }

    /* 0x00E55BE4-0x00E55BEA */
    ACL_$EXIT_SUPER();
    return result;
}
